package com.practice;

public class Autoboxing {

	public static void main(String[] args) {
		
		//autoboxing :converting  converting primitive data type into the wrapper object data type
		// TODO Auto-generated method stub
		int n=5;
		Integer m =n;
		
		
		System.out.println("primitive data:"+n);
		System.out.println("Wrapper object value:"+m);
		

	}

}
